Career::Career()
{
    int i;
    totalStatPointsIncreased=0;
    initKSConfigStruct(&cfg);
    for(i = 0; i < 9; i++)
        boards[i] = false;
    spin = speed = jump = balance = 0;
    my_id = 14;
    strcpy(myInitials, "");
